// node --test: the MainActivity transform of withRecentsScreenshotDisabled (runs in `npm test`).

const assert = require('node:assert/strict');
const { describe, it } = require('node:test');

const withRecentsScreenshotDisabled = require('./withRecentsScreenshotDisabled');

const { addRecentsScreenshotDisabled, RECENTS_LINE } = withRecentsScreenshotDisabled;

// MainActivity.kt as generated by the Expo SDK 58 template (abridged, onCreate verbatim).
const TEMPLATE = `package dev.narhi.statementimport

import android.os.Build
import android.os.Bundle

import com.facebook.react.ReactActivity

class MainActivity : ReactActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    // Set the theme to AppTheme BEFORE onCreate to support
    // coloring the background, status bar, and navigation bar.
    // This is required for expo-splash-screen.
    setTheme(R.style.AppTheme);
    super.onCreate(null)
  }

  override fun getMainComponentName(): String = "main"
}
`;

const WITHOUT_ON_CREATE = `package dev.example

import com.facebook.react.ReactActivity

class MainActivity : ReactActivity() {
  override fun getMainComponentName(): String = "main"
}
`;

const count = (src, needle) => src.split(needle).length - 1;

describe('addRecentsScreenshotDisabled', () => {
  it('inserts the API 33+ call right after super.onCreate(null) in the template onCreate', () => {
    const out = addRecentsScreenshotDisabled(TEMPLATE);
    assert.equal(count(out, RECENTS_LINE), 1);
    assert.match(
      out,
      /setTheme\(R\.style\.AppTheme\);\n {4}super\.onCreate\(null\)\n {4}\/\/ .*\n {4}if \(android\.os\.Build\.VERSION\.SDK_INT >= 33\) setRecentsScreenshotEnabled\(false\)\n {2}\}/,
    );
    // Everything else is untouched.
    assert.equal(out.replace(/\n {4}\/\/ statement-import:.*\n {4}if .*\n/, '\n'), TEMPLATE);
  });

  it('is idempotent: a second prebuild run does not duplicate the call', () => {
    const once = addRecentsScreenshotDisabled(TEMPLATE);
    const twice = addRecentsScreenshotDisabled(once);
    assert.equal(twice, once);
    assert.equal(count(twice, 'setRecentsScreenshotEnabled'), 1);
  });

  it('adds an onCreate override when MainActivity has none', () => {
    const out = addRecentsScreenshotDisabled(WITHOUT_ON_CREATE);
    assert.equal(count(out, 'override fun onCreate('), 1);
    assert.equal(count(out, 'super.onCreate(savedInstanceState)'), 1);
    assert.equal(count(out, RECENTS_LINE), 1);
    assert.ok(out.indexOf('super.onCreate') < out.indexOf(RECENTS_LINE));
    assert.equal(addRecentsScreenshotDisabled(out), out);
  });

  it('fails loudly instead of guessing when it cannot place the call', () => {
    assert.throws(() => addRecentsScreenshotDisabled('class Other : ReactActivity() {\n}\n'));
    assert.throws(() =>
      addRecentsScreenshotDisabled(
        'class MainActivity : ReactActivity() {\n  override fun onCreate(b: Bundle?) {\n  }\n}\n',
      ),
    );
  });
});

describe('withRecentsScreenshotDisabled (mod wiring)', () => {
  const run = async (language, contents) => {
    const config = withRecentsScreenshotDisabled({ name: 'test', slug: 'test' });
    const mod = config.mods.android.mainActivity;
    return mod({
      name: 'test',
      slug: 'test',
      modResults: { path: '/x/MainActivity.kt', language, contents },
      modRequest: { platform: 'android', modName: 'mainActivity', projectRoot: '/x' },
      modRawConfig: { name: 'test', slug: 'test' },
    });
  };

  it('patches the Kotlin MainActivity through withMainActivity', async () => {
    const result = await run('kt', TEMPLATE);
    assert.equal(count(result.modResults.contents, RECENTS_LINE), 1);
  });

  it('refuses a Java MainActivity', async () => {
    await assert.rejects(run('java', 'class MainActivity {}'));
  });
});
